    test('[TC_PETSTORE_USER_POST_003] Manage an user end to end: create, view, update and delete it; it is gone afterwards', async ({ api, data }) => {
      const input = data.entry('valid', 'TC_PETSTORE_USER_POST_003');
      // 1. create
      const created = await api.send({ method: 'POST', path: '/user', identity: 'default', body: input.body });
      expectStatus(created, [201]);
      expectJsonContentType(created);
      expectResponseTime(created, limits.responseTimeMs);
      expectEcho(input.body, created.json);
      const id = getAtPath(created.json, 'username');
      expect(['string', 'number'], 'create response returns an id').toContain(typeof id);
      const itemId = id as string | number;
      let deleted = false;
      try {
        // 2. read back - created data must be retrievable and identical
        const read = await api.send({ method: 'GET', path: '/user/{username}', identity: 'default', pathParams: { username: itemId } });
        expectStatus(read, [200]);
        expectSchema(read, S.UserUsernameGetResponse);
        expectEcho(input.body, read.json);
        // 3. full update
        const updated = await api.send({ method: 'PUT', path: '/user/{username}', identity: 'default', pathParams: { username: itemId }, body: input.updateBody });
        expectStatus(updated, [200]);
        expectEcho(input.updateBody, updated.json);
        const reread = await api.send({ method: 'GET', path: '/user/{username}', identity: 'default', pathParams: { username: itemId } });
        expectStatus(reread, [200]);
        expectEcho(input.updateBody, reread.json);
        // 5. delete, then the resource must be gone
        const removed = await api.send({ method: 'DELETE', path: '/user/{username}', identity: 'default', pathParams: { username: itemId } });
        expectStatus(removed, [200]);
        deleted = true;
        const gone = await api.send({ method: 'GET', path: '/user/{username}', identity: 'default', pathParams: { username: itemId } });
        expectStatus(gone, [404]);
      } finally {
        if (!deleted) await api.remove('user', itemId);
      }
    });

